create table if not exists public.guilds(id uuid primary key default gen_random_uuid(),name text not null,tag text not null unique,owner_id uuid not null references auth.users(id) on delete cascade,visibility text not null default 'public' check(visibility in('public','invite_only')),xp bigint not null default 0,created_at timestamptz not null default now());create table if not exists public.guild_members(guild_id uuid not null references public.guilds(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'member' check(role in('owner','officer','member')),contribution_xp bigint not null default 0,joined_at timestamptz not null default now(),primary key(guild_id,user_id));create table if not exists public.social_raids(id uuid primary key default gen_random_uuid(),guild_id uuid references public.guilds(id) on delete cascade,title text not null,boss_hp bigint not null check(boss_hp>0),damage bigint not null default 0 check(damage>=0),starts_at timestamptz not null,ends_at timestamptz not null,created_at timestamptz not null default now(),check(ends_at>starts_at));create table if not exists public.raid_contributions(raid_id uuid not null references public.social_raids(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,damage bigint not null default 0 check(damage>=0),updated_at timestamptz not null default now(),primary key(raid_id,user_id));alter table public.guilds enable row level security;alter table public.guild_members enable row level security;alter table public.social_raids enable row level security;alter table public.raid_contributions enable row level security;revoke all on public.guilds,public.guild_members,public.social_raids,public.raid_contributions from anon,authenticated;grant select on public.guilds,public.guild_members,public.social_raids,public.raid_contributions to authenticated;create policy guilds_read on public.guilds for select to authenticated using(visibility='public'or exists(select 1 from public.guild_members m where m.guild_id=id and m.user_id=(select auth.uid())));create policy guild_members_read on public.guild_members for select to authenticated using(exists(select 1 from public.guilds g where g.id=guild_id and(g.visibility='public'or exists(select 1 from public.guild_members me where me.guild_id=g.id and me.user_id=(select auth.uid())))));create policy raids_read on public.social_raids for select to authenticated using(guild_id is null or exists(select 1 from public.guilds g where g.id=guild_id and(g.visibility='public'or exists(select 1 from public.guild_members m where m.guild_id=g.id and m.user_id=(select auth.uid())))));create policy raid_contrib_read on public.raid_contributions for select to authenticated using(exists(select 1 from public.social_raids r where r.id=raid_id));create or replace function public.create_guild(p_name text,p_tag text,p_visibility text default'public')returns uuid language plpgsql security definer set search_path='' as $$declare gid uuid;begin if length(trim(p_name))<3 or length(trim(p_name))>40 then raise exception 'INVALID_GUILD_NAME';end if;if p_tag!~'^[A-Z0-9]{2,5}$' then raise exception 'INVALID_GUILD_TAG';end if;insert into public.guilds(name,tag,owner_id,visibility)values(trim(p_name),p_tag,(select auth.uid()),p_visibility)returning id into gid;insert into public.guild_members(guild_id,user_id,role)values(gid,(select auth.uid()),'owner');return gid;end;$$;create or replace function public.join_guild(p_guild uuid)returns void language plpgsql security definer set search_path='' as $$begin if not exists(select 1 from public.guilds where id=p_guild and visibility='public')then raise exception 'GUILD_NOT_JOINABLE';end if;insert into public.guild_members(guild_id,user_id)values(p_guild,(select auth.uid()))on conflict do nothing;end;$$;create or replace function public.contribute_raid_damage(p_raid uuid,p_damage bigint)returns bigint language plpgsql security definer set search_path='' as $$declare total bigint;begin if p_damage<=0 or p_damage>100000 then raise exception 'INVALID_DAMAGE';end if;if not exists(select 1 from public.social_raids r where r.id=p_raid and now()>=r.starts_at and now()<r.ends_at and(r.guild_id is null or exists(select 1 from public.guild_members m where m.guild_id=r.guild_id and m.user_id=(select auth.uid()))))then raise exception 'RAID_NOT_ACTIVE';end if;insert into public.raid_contributions(raid_id,user_id,damage)values(p_raid,(select auth.uid()),p_damage)on conflict(raid_id,user_id)do update set damage=public.raid_contributions.damage+excluded.damage,updated_at=now();update public.social_raids set damage=least(boss_hp,damage+p_damage)where id=p_raid returning damage into total;return total;end;$$;revoke all on function public.create_guild(text,text,text),public.join_guild(uuid),public.contribute_raid_damage(uuid,bigint) from public,anon;grant execute on function public.create_guild(text,text,text),public.join_guild(uuid),public.contribute_raid_damage(uuid,bigint) to authenticated;